    public async Task<Result> AtualizarAsync(long id, CriarDiarioPublicacaoRequest r, CancellationToken ct) { if (!Tenant.TenantId.HasValue) return TenantFailure(); if (!await CanAsync(ProcessosPermissoes.DiarioEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AtualizarAsync(Tenant.TenantId.Value, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); }
    public async Task<Result> PublicarAsync(long id, PublicarDiarioRequest r, CancellationToken ct) { if (!Tenant.TenantId.HasValue) return TenantFailure(); if (!UsuarioId.HasValue) return AuthFailure(); if (!await CanAsync(ProcessosPermissoes.DiarioPublicar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.PublicarAsync(Tenant.TenantId.Value, id, UsuarioId.Value, ct).ConfigureAwait(false); await Audit.RegistrarAsync("processos", "PUBLICAR_DIARIO", "sigov.diario_oficial_publicacao", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); }
    public async Task<Result<long>> CriarAtoAsync(long id, CriarAtoOficialRequest r, CancellationToken ct) { if (!Tenant.TenantId.HasValue) return TenantFailureLong(); if (!await CanAsync(ProcessosPermissoes.DiarioCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); _ = new AtoOficial(id); var atoId = await _repo.CriarAtoAsync(Tenant.TenantId.Value, id, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("processos", "CRIAR_ATO", "sigov.ato_oficial", atoId.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(atoId); }
    public async Task<Result<IReadOnlyCollection<AtoOficialResponse>>> ListarAtosAsync(long id, CancellationToken ct) { if (!Tenant.TenantId.HasValue) return TenantFailure<IReadOnlyCollection<AtoOficialResponse>>(); if (!await CanAsync(ProcessosPermissoes.DiarioVisualizar, ct).ConfigureAwait(false)) return Result<IReadOnlyCollection<AtoOficialResponse>>.Failure("403"); return Result<IReadOnlyCollection<AtoOficialResponse>>.Success(await _repo.ListarAtosAsync(Tenant.TenantId.Value, id, ct).ConfigureAwait(false)); }
}
